    r=subprocess.run(['./executable']+args, capture_output=True, text=True)
    for line in r.stderr.splitlines():
        if "reminds you" in line:
            return line
    return "NO QUOTE:"+repr(r.stderr[:200])+repr(r.stdout[:200])

