{"command": "python3 <<'PY' > /tmp/nofile_test.txt 2>&1
import subprocess
def run(args):
    r=subprocess.run(['./executable']+args, capture_output=True, text=True, timeout=10)
    return r.returncode, r.stdout, r.stderr

# Get command list by parsing commands.txt
import re
with open('/tmp/commands.txt') as f:
    txt=f.read()
# extract first word per line after spaces
cmds=[]
for line in txt.splitlines():
    m=re.match(r'\s{4}(\S+)\s', line)
    if m:
        cmds.append(m.group(1))
print(f"found {len(cmds)} cmds: {cmds[:10]}...")
for cmd in cmds:
    try:
        rc,out,err = run([cmd])
        # extract error type
        if rc==0:
            status=f"OK out={len(out)}"
            if out:
                status+=f" out_head={repr(out[:120])}"
        else:
            # find error snippet
            snippet=""
            for pat in ["Error in user input:", "Invalid", "Inconsistency", "Required option", "No trajectory", "Fatal error"]:
                if pat in err:
                    idx=err.find(pat)
                    snippet=err[idx:idx+150].replace("\n"," | ")
                    break
            if not snippet:
                snippet=err[:150].replace("\n"," | ")
            status=f"ERR rc={rc} {snippet[:150]}"
        print(f"{cmd:20} {status}")
    except Exception as e:
        print(f"{cmd:20} EXC {e}")
PY
cat /tmp/nofile_test.txt"}

