                err = make_unknown_option(prog, exe, cwd, cmdline_str, a, False)
                return ("error", (1, "", err))
            # strip dashes
            tmp = a.lstrip("-")
            # tmp could be "h", "noh", "quiet", "noquiet", "nice", etc., or "help", "H", etc.
