            found = None
            is_no = False
            base = None
            # Try exact match first
            if tmp in WRAPPER_BOOL_OPTS:
                base = tmp; is_no = False; found = "bool"
            elif tmp in WRAPPER_INT_OPTS:
                base = tmp; is_no = False; found = "int"
            elif tmp.startswith("no") and tmp[2:] in WRAPPER_BOOL_OPTS:
                base = tmp[2:]; is_no = True; found = "bool"
            else:
                # unknown option
                prog = program_basename
                err = make_unknown_option(prog, exe, cwd, cmdline_str, a, False)
                return ("error", (1, "", err))
            # Check duplicate
            if base in seen:
                prog = program_basename
                # error opt name as given? For duplicate, original shows the second occurrence's name? e.g., "-quiet -noquiet" error shows "-noquiet"
                # So use current arg a
                hdr = error_header_wrapper(prog, exe, cwd, cmdline_str)
                body = f"-------------------------------------------------------\nProgram:     {prog}, version {VERSION}\nSource file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\nFunction:    void gmx::CommandLineParser::parse(int*, char**)\n\nError in user input:\nInvalid command-line options\n  In command-line option {a}\n    Option specified multiple times\n\n" + FOOTER
                return ("error", (1, "", hdr+body))
            seen[base] = a
            if found == "bool":
                flags[base] = (False if is_no else True)
                pos += 1
                continue
            else: # int
                if base == "nice":
                    # always error Too few (as observed)
                    prog = program_basename
                    err = make_too_few(prog, exe, cwd, cmdline_str, a, False)
                    return ("error", (1, "", err))
                elif base == "debug":
                    # does not consume next arg, just set flag (default 0? if no value, keep 0? Actually -debug without value uses default 0 and succeeds)
                    # If next arg is numeric? It still doesn't consume (as observed, -debug 1 treats 1 as command)
                    # So just set and continue without consuming
                    flags[base] = 0
                    pos += 1
                    continue
        else:
            # non-option => command
            cmd = a
            cmd_idx = pos
            break
        pos += 1
    # After loop, if h or version true, handle immediate (ignore command and rest)
    # Note: wrapper h/version trigger regardless of value? For wrapper, if h true (i.e., -h present, not -noh), trigger.
    # What about -h with value? Wrapper h doesn't consume, so no value handling. Good.
    if flags.get("h"):
        # show wrapper help (with hidden/copyright/quiet handling)
        hidden = flags.get("hidden", False)
        quiet = flags.get("quiet", False)
        copyright_flag = flags.get("copyright", False)
        # help stdout
        help_text = get_wrapper_help(hidden)
        if help_text is None:
            help_text = ""
        if copyright_flag and not quiet:
            # stdout help, stderr copyright+quote
            prog = program_basename
            err = copyright_stderr(prog, exe, cwd, cmdline_str, quiet=False)
            return ("help_copyright", (0, help_text, err))
        elif copyright_flag and quiet:
            # quiet suppresses copyright? Earlier -quiet -copyright gave no err, just help. Good.
            return ("help", (0, help_text, ""))
        else:
            if quiet:
                return ("help", (0, help_text, ""))
            else:
                prog = program_basename
                err = stderr_header(prog, exe, cwd, cmdline_str, quiet=False)
                return ("help", (0, help_text, err))
    if flags.get("version"):
        quiet = flags.get("quiet", False)  # quiet doesn't affect version stdout? Actually version stdout always has header, even with quiet. Good.
        copyright_flag = flags.get("copyright", False)
        prog = program_basename
        if copyright_flag:
            out = copyright_version_stdout(prog, exe, cwd, cmdline_str)
            return ("version", (0, out, ""))
        else:
            out = version_stdout(prog, exe, cwd, cmdline_str)
            return ("version", (0, out, ""))
    # If no command, show wrapper help (default) with flags
    if cmd is None:
        hidden = flags.get("hidden", False)
        quiet = flags.get("quiet", False)
        copyright_flag = flags.get("copyright", False)
        help_text = get_wrapper_help(hidden)
        if copyright_flag and not quiet:
            prog = program_basename
            err = copyright_stderr(prog, exe, cwd, cmdline_str, quiet=False)
            return ("help", (0, help_text, err))
        else:
            if quiet:
                return ("help", (0, help_text, ""))
            else:
                # check if copyright? already handled
                prog = program_basename
                err = stderr_header(prog, exe, cwd, cmdline_str, quiet=False)
                return ("help", (0, help_text, err))
    # Check if cmd is valid command
    cmds = get_commands()
    if cmd not in cmds:
        prog = program_basename
        err = make_wrapper_unknown_cmd(prog, exe, cwd, cmdline_str, cmd)
        return ("error", (1, "", err))
    # Valid command: dispatch to subcommand with remaining args and wrapper flags
    # Wrapper flags quiet/copyright/backup/hidden/debug/fpexcept are passed through? For subcommand, they affect behavior.
    # Return dispatch
    remaining = args[cmd_idx+1:]
    # wrapper flags to pass: quiet, copyright, backup, hidden, debug, fpexcept (and maybe nice? but nice always errored, so not present)
    return ("dispatch", (cmd, remaining, flags))

